configuration.alarmDetailsBuildJs:
var details = {};
details.water_level_cm = msg.water_level_cm;
details.rainfall_mm = msg.rainfall_mm || 0;
details.temperature_c = msg.temperature_c || 0;
return details;

configuration.jsScript:
var stationName = metadata.deviceName || metadata.device_id || 'Trạm Quan Trắc';
var waterLevel = msg.details && msg.details.water_level_cm ? msg.details.water_level_cm : (msg.water_level_cm || 'N/A');
var rain = msg.details && msg.details.rainfall_mm !== undefined ? msg.details.rainfall_mm : (msg.rainfall_mm || 0);

var discordPayload = {
  "content": "🚨 **[THINGSBOARD ALARM] CẢNH BÁO MỰC NƯỚC NGUY HIỂM** 🚨",
  "embeds": [{
    "title": "Trạm: " + stationName,
    "description": "Hệ thống ThingsBoard IoT vừa phát hiện mực nước dâng cao vượt ngưỡng báo động đỏ!",
    "color": 15158332,
    "fields": [
      {"name": "📍 Thiết bị / Trạm", "value": "`" + stationName + "`", "inline": true},
      {"name": "⚠️ Mức độ", "value": "**CRITICAL (Báo động đỏ)**", "inline": true},
      {"name": "🌊 Mực nước đo", "value": "**" + waterLevel + " cm**", "inline": true},
      {"name": "🌧️ Lượng mưa", "value": rain + " mm", "inline": true},
      {"name": "⚡ Ngưỡng quy định", "value": "≥ 50 cm", "inline": true},
      {"name": "🕒 Thời gian ghi nhận", "value": new Date().toLocaleString("vi-VN", {timeZone: "Asia/Ho_Chi_Minh"}), "inline": true}
    ],
    "footer": {
      "text": "ThingsBoard Rule Engine • HCM Smart Flood Monitor"
    },
    "timestamp": new Date().toISOString()
  }]
};

return {msg: discordPayload, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST'};
